create table if not exists profiles(id uuid primary key default gen_random_uuid(),user_id uuid,name text not null,age int not null check(age between 6 and 10),avatar text default '🐱',created_at timestamptz default now(),updated_at timestamptz default now());create table if not exists worlds(id text primary key,title text not null,description text,icon text,order_index int,is_active boolean default true);create table if not exists topics(id text primary key,world_id text references worlds(id),title text not null,description text,order_index int);create table if not exists lessons(id text primary key,topic_id text references topics(id),title text not null,description text,age_min int,age_max int,difficulty int,learning_goal jsonb,order_index int,is_active boolean default true);create table if not exists activities(id text primary key,lesson_id text references lessons(id),type text not null,order_index int,content jsonb,config jsonb);create table if not exists lesson_progress(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,lesson_id text references lessons(id),status text,score int default 0,mastery numeric default 0,attempts int default 0,started_at timestamptz,completed_at timestamptz,xp int default 0,stars int default 0,unique(profile_id,lesson_id));create table if not exists activity_attempts(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,activity_id text references activities(id),is_correct boolean,answer jsonb,time_spent int,created_at timestamptz default now());